package com.arjunren.coop;import io.javalin.Javalin;import java.math.*;import java.sql.*;import java.util.*;
public final class Main{public static void main(String[]z){var db=new Database(System.getenv().getOrDefault("DB_URL","jdbc:h2:file:./data/coop;AUTO_SERVER=TRUE"));db.migrate();var pw=new Passwords();seed(db,pw);var auth=new Auth(db,pw);var service=new AccountService(db);Javalin.create(c->{var r=c.routes;r.exception(SecurityException.class,(e,x)->x.status(403).json(err("AUTH_ERROR","Unauthorized")));r.exception(IllegalArgumentException.class,(e,x)->x.status(400).json(err("VALIDATION_ERROR",e.getMessage())));r.exception(IllegalStateException.class,(e,x)->x.status(409).json(err("CONFLICT",e.getMessage())));r.post("/api/auth/login",x->{var q=x.bodyAsClass(Login.class);x.json(Map.of("data",auth.login(q.username,q.password)));});r.get("/api/accounts",x->{var p=auth.require(x.header("Authorization"),"ADMIN","TELLER","MEMBER");var sql="SELECT a.id,a.member_id,m.member_number,m.full_name,a.balance,a.updated_at FROM accounts a JOIN members m ON m.id=a.member_id"+(p.role().equals("MEMBER")?" WHERE a.member_id=?":"");try(var cn=db.connection();var s=cn.prepareStatement(sql)){if(p.role().equals("MEMBER"))s.setLong(1,p.memberId());x.json(Map.of("data",rows(s)));}});r.post("/api/accounts/{id}/movements",x->{var p=auth.require(x.header("Authorization"),"ADMIN","TELLER");var q=x.bodyAsClass(Move.class);x.status(201).json(Map.of("data",service.move(Long.parseLong(x.pathParam("id")),q.type,q.amount,q.reference,p.userId())));});r.post("/api/members",x->{auth.require(x.header("Authorization"),"ADMIN");var q=x.bodyAsClass(Member.class);try(var cn=db.connection()){cn.setAutoCommit(false);try(var s=cn.prepareStatement("INSERT INTO members(member_number,full_name,email) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.memberNumber);s.setString(2,q.fullName);s.setString(3,q.email);s.executeUpdate();try(var k=s.getGeneratedKeys()){k.next();try(var a=cn.prepareStatement("INSERT INTO accounts(member_id) VALUES(?)")){a.setLong(1,k.getLong(1));a.executeUpdate();}}cn.commit();x.status(201).json(Map.of("data",q));}}});r.get("/api/ledger",x->{auth.require(x.header("Authorization"),"ADMIN","TELLER");try(var cn=db.connection();var s=cn.prepareStatement("SELECT * FROM ledger ORDER BY created_at DESC LIMIT 100")){x.json(Map.of("data",rows(s)));}});r.get("/api/dashboard",x->{auth.require(x.header("Authorization"),"ADMIN");try(var cn=db.connection();var s=cn.prepareStatement("SELECT COUNT(*) members,COALESCE(SUM(balance),0) total_savings FROM accounts")){x.json(Map.of("data",rows(s).getFirst()));}});}).start(Integer.parseInt(System.getenv().getOrDefault("PORT","8080")));}
static List<Map<String,Object>>rows(PreparedStatement s)throws SQLException{try(var q=s.executeQuery()){var o=new ArrayList<Map<String,Object>>();var m=q.getMetaData();while(q.next()){var x=new LinkedHashMap<String,Object>();for(int i=1;i<=m.getColumnCount();i++)x.put(m.getColumnLabel(i).toLowerCase(),q.getObject(i));o.add(x);}return o;}}static Map<String,Object>err(String c,String m){return Map.of("error",Map.of("code",c,"message",m));}static void seed(Database d,Passwords p){try(var c=d.connection()){if(c.createStatement().executeQuery("SELECT COUNT(*) FROM users").next()){try(var q=c.createStatement().executeQuery("SELECT COUNT(*) FROM users")){q.next();if(q.getInt(1)>0)return;}}c.createStatement().execute("INSERT INTO members(member_number,full_name,email) VALUES('MEM-001','Demo Member','member@example.com')");c.createStatement().execute("INSERT INTO accounts(member_id,balance) VALUES(1,1000)");try(var s=c.prepareStatement("INSERT INTO users(username,password_hash,role,member_id) VALUES(?,?,?,?)")){for(var u:new Object[][]{{"admin","ADMIN",null},{"teller","TELLER",null},{"member","MEMBER",1L}}){s.setString(1,(String)u[0]);s.setString(2,p.hash("ChangeMe123!"));s.setString(3,(String)u[1]);s.setObject(4,u[2]);s.addBatch();}s.executeBatch();}}catch(SQLException e){throw new IllegalStateException(e);}}record Login(String username,String password){}record Move(String type,BigDecimal amount,String reference){}record Member(String memberNumber,String fullName,String email){}}
